// One registration in the single Activity — new destinations are tracked for free
@Composable
private fun TrackScreenViews(nav: NavHostController) {
  val analytics = LocalAnalytics.current
  LaunchedEffect(nav) {
    nav.currentBackStackEntryFlow
      .mapNotNull { it.destination.route }   // "order/{orderId}" — the pattern, not the value
      .distinctUntilChanged()                // a recomposition must not re-log the same screen
      .collect { route -> analytics.log(Event.ScreenViewed(screen = route)) }
  }
}

@Composable
fun App() {
  val nav = rememberNavController()
  TrackScreenViews(nav)
  NavHost(nav, startDestination = "cart") {
    composable("cart") { CartScreen() }
    composable("order/{orderId}") { OrderScreen() }
  }
}

