// One flow instance = one id, minted at the entry point, carried to the outcome
class CheckoutFunnel(private val analytics: Analytics, private val clock: Clock) {
  private var checkoutId: String? = null
  private var seq = 0
  private val fired = mutableSetOf<String>()

  fun start(cartValueCents: Long) {
    checkoutId = UUID.randomUUID().toString()
    seq = 0
    fired.clear()
    step("cart_viewed", 1, mapOf("cart_value_cents" to cartValueCents))
  }

  fun step(step: String, index: Int, extra: Map<String, Any?> = emptyMap()) {
    val id = checkoutId ?: return        // a step with no flow id is unjoinable — do not send it
    if (!fired.add(step)) return         // re-entering the screen must not re-fire the step
    analytics.log("checkout_step", mapOf(
      "checkout_id" to id,
      "step" to step,
      "step_index" to index,
      "seq" to seq++,                    // breaks same-millisecond ties
      "client_ts" to clock.millis()
    ) + extra)
  }

  fun failed(reason: String) = step("failed", 99, mapOf("reason" to reason))

  fun completed(orderId: String) {
    step("confirmed", 4, mapOf("order_id" to orderId))
    checkoutId = null
  }
}

// Identity: the same human before and after login, or the funnel splits into two users
fun onLogin(userId: String) {
  analytics.alias(anonymousId = analytics.deviceId, userId = userId)
  analytics.identify(userId)
}

@Entity(tableName = "events")
data class QueuedEvent(
  @PrimaryKey val insertId: String,   // minted here, persisted with the row, stable across retries
  val name: String,
  val payload: String,
  val clientTs: Long,
  val seq: Long
)

class DiskQueueAnalytics(private val dao: EventDao, private val scope: CoroutineScope) : Analytics {

  override fun log(name: String, props: Map<String, Any?>) {
    val row = QueuedEvent(
      insertId = UUID.randomUUID().toString(),
      name = name,
      payload = json.encodeToString(props),
      clientTs = System.currentTimeMillis(),
      seq = nextSeq()
    )
    scope.launch { dao.insert(row); dao.trimOldest(MAX_ROWS) }  // cap it, dropping oldest first
  }

  suspend fun flush() {
    while (true) {
      val batch = dao.oldest(limit = 30)
      if (batch.isEmpty()) return
      val ok = runCatching { api.upload(batch) }.getOrDefault(false)
      if (!ok) return                  // leave the rows; the worker retries with backoff
      dao.delete(batch)                // delete only after a 2xx
    }
  }
}

// Background is the last moment you are guaranteed to run: hand it to WorkManager, do not
// start a long upload in onStop and hope the process lives long enough to finish it.
class FlushOnBackground(private val work: WorkManager) : DefaultLifecycleObserver {
  override fun onStop(owner: LifecycleOwner) {
    work.enqueueUniqueWork("analytics-flush", ExistingWorkPolicy.KEEP,
      OneTimeWorkRequestBuilder<FlushWorker>()
        .setConstraints(Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build())
        .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
        .build())
  }
}

data class Batch(
  val events: List<QueuedEvent>,
  val clientUploadTime: Long          // stamped at upload, not at track
)

@Volatile var skewMs: Long = 0        // positive means this device runs fast

suspend fun upload(rows: List<QueuedEvent>): Boolean {
  val batch = Batch(rows, clientUploadTime = System.currentTimeMillis())
  val resp = api.post(batch)
  skewMs = batch.clientUploadTime - resp.serverUploadTime
  return resp.isSuccessful
}

// The server then rewrites each event's time, the shape Amplitude uses:
//   event_time = client_event_time - (client_upload_time - server_upload_time)
// Offline ordering is preserved; a two-day-fast clock is cancelled out.

// ❌ Duration from two wall-clock reads: NTP can move the clock between them
val startedAt = System.currentTimeMillis()
// ... user fills in the form, the clock is corrected by 90 s ...
val wrongMs = System.currentTimeMillis() - startedAt   // can come out negative

// ✅ Monotonic for elapsed time, wall clock only for "when"
val startedElapsed = SystemClock.elapsedRealtime()     // counts from boot, NTP cannot move it

fun finishStep() = analytics.log("checkout_step", mapOf(
  "duration_ms" to (SystemClock.elapsedRealtime() - startedElapsed),
  "client_ts" to System.currentTimeMillis()            // the server still stamps its own
))

// ✅ The id belongs to the event: minted once, persisted with it, reused on every retry
fun log(name: String, props: Map<String, Any?>) = dao.insert(
  QueuedEvent(
    insertId = UUID.randomUUID().toString(),
    name = name,
    payload = json.encodeToString(props),
    clientTs = System.currentTimeMillis()
  )
)

// ❌ Minted at send time: every retry carries a new id, so every retry is a new row upstream
suspend fun uploadWrong(rows: List<QueuedEvent>) =
  api.upload(rows.map { it.toDto(insertId = UUID.randomUUID().toString()) })

// With a stable id the retry loop is allowed to be dumb
suspend fun flush(rows: List<QueuedEvent>) {
  var attempt = 0
  while (attempt < 5) {
    val ok = runCatching { api.upload(rows.map { it.toDto(insertId = it.insertId) }) }.isSuccess
    if (ok) { dao.delete(rows); return }
    delay(backoffWithJitter(attempt++))   // a timeout may already have committed: resend anyway
  }
}

// Money is where "roughly right" stops being acceptable: key on the transaction itself,
// so a replayed queue — or a second device syncing the same order — cannot inflate revenue.
fun logPurchase(orderId: String, cents: Long) = dao.insert(
  QueuedEvent(
    insertId = "purchase:$orderId",
    name = "purchase_completed",
    payload = json.encodeToString(mapOf("order_id" to orderId, "value_cents" to cents)),
    clientTs = System.currentTimeMillis()
  )
)

data class SessionRow(val userId: String, val version: String, val crashed: Boolean)

// The two numbers differ only in what you count distinct on
fun crashFreeSessions(rows: List<SessionRow>): Double =
  1.0 - rows.count { it.crashed }.toDouble() / rows.size

fun crashFreeUsers(rows: List<SessionRow>): Double {
  val users = rows.mapTo(mutableSetOf()) { it.userId }.size
  val hit = rows.filter { it.crashed }.mapTo(mutableSetOf()) { it.userId }.size  // once per person
  return 1.0 - hit.toDouble() / users
}

// Alerting is always per version and always against the previous one.
// The app-wide aggregate hides a bad release behind the healthy installed base.
fun rolloutGate(current: Release, previous: Release, dailyUsers: Int): Gate {
  val regression = previous.crashFreeSessions - current.crashFreeSessions
  val affected = (dailyUsers * (1.0 - current.crashFreeUsers)).roundToInt()
  return when {
    current.sessions < 5_000 -> Gate.Wait                 // too few sessions to mean anything
    regression > 0.003 -> Gate.Halt(affected)             // 0.3 pp worse than what it replaces
    regression > 0.001 -> Gate.Hold(affected)             // pause the rollout, keep the build
    else -> Gate.Continue
  }
}

// Report the count next to the percentage: at 2M users "99.5% crash-free" is 10,000 people.
fun headline(r: Release, monthlyUsers: Int) =
  "%.2f%% crash-free users — %d people".format(r.crashFreeUsers * 100, ((1 - r.crashFreeUsers) * monthlyUsers).roundToInt())

// A hang detector: the main looper is healthy only if it can still answer
class MainThreadWatchdog(
  private val thresholdMs: Long = 4_000,
  private val onHang: (Array<StackTraceElement>, Long) -> Unit
) {
  private val main = Handler(Looper.getMainLooper())
  @Volatile private var pending = false

  fun start() = thread(isDaemon = true, name = "hang-watchdog") {
    while (true) {
      pending = true
      val postedAt = SystemClock.elapsedRealtime()
      main.post { pending = false }               // only the main thread can clear the flag
      while (pending && SystemClock.elapsedRealtime() < postedAt + thresholdMs) Thread.sleep(200)
      if (pending) {
        // Capture the stack while it is frozen — after it recovers the evidence is gone
        val stack = Looper.getMainLooper().thread.stackTrace
        while (pending) Thread.sleep(200)         // one report per hang, not one per tick
        onHang(stack, SystemClock.elapsedRealtime() - postedAt)  // duration is known only once it unblocks
      }
      Thread.sleep(1_000)
    }
  }
}

// The freeze the system already recorded for you, read once on the next launch
fun reportPreviousAnr(context: Context) {
  if (Build.VERSION.SDK_INT < Build.VERSION_CODES.R) return
  context.getSystemService(ActivityManager::class.java)
    .getHistoricalProcessExitReasons(context.packageName, 0, 5)
    .firstOrNull { it.reason == ApplicationExitInfo.REASON_ANR }
    ?.traceInputStream?.bufferedReader()
    ?.use { analytics.log("previous_anr", mapOf("trace" to it.readText().take(8_000))) }
}

class UploadFailed(val step: Step, cause: Throwable) : Exception("upload failed", cause)

// WRONG - the order id is in the message, so grouping forks one bug per user
suspend fun uploadBad(order: Order) = try {
  api.upload(order)
} catch (e: IOException) {
  Firebase.crashlytics.recordException(
    RuntimeException("upload failed for order ${order.id} at ${api.baseUrl}")
  )
}

// RIGHT - stable type for grouping, variable state in keys, the trail in log()
suspend fun upload(order: Order, step: Step, attempt: Int) = try {
  api.upload(order)
} catch (e: IOException) {
  Firebase.crashlytics.apply {
    setCustomKey("upload_step", step.name)            // 64 keys per report
    setCustomKey("network", connectivity.current().name)
    setCustomKey("flag_upload_v2", flags.uploadV2)
    setCustomKey("session_id", session.id)
    log("upload $attempt/3 failed: ${e.javaClass.simpleName}")   // 64 KB rolling buffer
    if (attempt == 3) recordException(UploadFailed(step, e))     // report once, not per retry
  }
}

// One shared helper collapses unrelated failures into one issue - split the grouping yourself
fun report(step: Step, cause: Throwable) = Sentry.withScope { scope ->
  scope.fingerprint = listOf("upload-failed", step.name)
  scope.setTag("upload_step", step.name)
  Sentry.captureException(UploadFailed(step, cause))
}

// Automatic breadcrumbs record full URLs - drop the query string before anything leaves
SentryAndroid.init(context) { options ->
  options.isSendDefaultPii = false
  options.maxBreadcrumbs = 100
  options.beforeBreadcrumb = SentryOptions.BeforeBreadcrumbCallback { crumb, _ ->
    crumb.data["url"] = (crumb.data["url"] as? String)?.substringBefore('?')
    crumb
  }
}

// Root span at the interaction - every child below shares this trace id
fun onCheckoutTap(scope: CoroutineScope) {
  val span = tracer.spanBuilder("checkout_tap").setSpanKind(SpanKind.CLIENT).startSpan()
  span.setAttribute("cart.items", cart.size.toLong())
  // ThreadLocal context does not survive a suspension point: carry it as a context element
  scope.launch(Context.current().with(span).asContextElement()) {
    try { repo.checkout() }
    catch (e: Exception) { span.setStatus(StatusCode.ERROR); span.recordException(e); throw e }
    finally { span.end() }
  }
}

// Inject W3C trace context so the server continues this trace instead of starting its own
class TraceHeaderInterceptor(
  private val propagator: TextMapPropagator = W3CTraceContextPropagator.getInstance()
) : Interceptor {
  override fun intercept(chain: Interceptor.Chain): Response {
    val builder = chain.request().newBuilder()
    propagator.inject(Context.current(), builder) { b, key, value -> b?.header(key, value) }
    return chain.proceed(builder.build())   // traceparent: 00-<traceId>-<spanId>-01
  }
}

// WRONG - a blind uniform rate lets the device throw away the incident you get paged about
val bad = Sampler.traceIdRatioBased(0.01)

// RIGHT - always keep what you will be asked to explain, sample the boring majority
class RuleSampler(private val rest: Sampler = Sampler.traceIdRatioBased(0.01)) : Sampler {
  override fun shouldSample(
    parent: Context, traceId: String, name: String, kind: SpanKind,
    attrs: Attributes, links: List<LinkData>
  ): SamplingResult =
    if (name == "cold_start" || name.startsWith("checkout")) SamplingResult.recordAndSample()
    else rest.shouldSample(parent, traceId, name, kind, attrs, links)

  override fun getDescription() = "always(checkout,cold_start)+1%"
}

val sampler = Sampler.parentBased(RuleSampler())   // children obey the root's decision

// WRONG - the splash screen now waits on the network on every single cold start
suspend fun startupBad() {
  remoteConfig.fetchAndActivate().await()     // up to fetchTimeoutInSeconds, default 60s
  showHome()
}

// RIGHT - defaults answer instantly, the fetch lands for the next screen or next launch
class ConfigGate(private val rc: FirebaseRemoteConfig) {
  fun init() {
    rc.setConfigSettingsAsync(remoteConfigSettings {
      minimumFetchIntervalInSeconds = if (BuildConfig.DEBUG) 0 else 3600
      fetchTimeoutInSeconds = 10
    })
    // Defaults = the safe branch you are already shipping, NOT the value you hope to enable
    rc.setDefaultsAsync(mapOf(
      "upload_v2_enabled" to false,            // a kill switch defaults to OFF
      "feed_page_size" to 20
    ))
    rc.fetchAndActivate()                      // fire and forget; nothing awaits it

    // Real-time updates: a kill switch reaches an open app in seconds
    rc.addOnConfigUpdateListener(object : ConfigUpdateListener {
      override fun onUpdate(update: ConfigUpdate) { rc.activate() }
      override fun onError(error: FirebaseRemoteConfigException) = Unit
    })
  }

  // Latched once per screen, so an activation cannot change the layout mid-session
  fun snapshot() = FeatureSet(
    uploadV2 = rc.getBoolean("upload_v2_enabled"),
    pageSize = rc.getLong("feed_page_size").toInt()
  )
}

// The first-session path is the one that is never tested - test it explicitly
@Test fun `no network on first launch falls back to the safe default`() {
  assertFalse(ConfigGate(freshConfigWithNoNetwork()).snapshot().uploadV2)
}

// Deterministic assignment - the warehouse recomputes exactly this from the same inputs
fun variantOf(exp: Experiment, userId: String): String {
  val bucket = Hashing.murmur3_32_fixed()
    .hashString("${exp.key}:$userId", Charsets.UTF_8)
    .asInt().toUInt().toInt() % 10_000
  var cursor = 0
  for ((name, weight) in exp.weights) {        // control 5000, variant 5000
    cursor += weight
    if (bucket < cursor) return name
  }
  return "control"
}

// WRONG - exposure at startup, and only for the variant: dilution plus a guaranteed SRM
fun onAppStart() {
  if (variantOf(checkoutExp, userId) == "variant") analytics.track("experiment_exposure")
}

// RIGHT - at first render, both arms, once per session
@Composable
fun CheckoutScreen(exp: ExperimentClient) {
  val variant = exp.variant(checkoutExp)       // pure lookup, no logging
  LaunchedEffect(checkoutExp.key) { exp.logExposure(checkoutExp, variant) }
  when (variant) {
    "v2" -> CheckoutV2()
    else -> CheckoutV1()                       // control is measured too
  }
}

class ExperimentClient(private val analytics: Analytics, private val userId: String) {
  private val logged = mutableSetOf<String>()
  fun logExposure(exp: Experiment, served: String) {
    if (!logged.add(exp.key)) return           // once per session per experiment
    analytics.track("experiment_exposure", mapOf(
      "experiment" to exp.key,
      "variant" to served,                     // what was served, not what was assigned
      "user_id" to userId
    ))
  }
}

// WRONG - comparing app versions is not an experiment, it is two populations in two weeks
val lift = metrics.forVersion("4.2.0").conversion / metrics.forVersion("4.1.0").conversion

// RIGHT - both arms in one binary, randomised inside the build
@Composable
fun CheckoutEntry(exp: ExperimentClient, flags: FeatureFlags) {
  // The kill switch outranks the experiment: the losing arm must die without a release
  if (!flags.checkoutExperimentEnabled) { CheckoutV1(); return }
  val variant = exp.variant(checkoutExp)
  LaunchedEffect(Unit) { exp.logExposure(checkoutExp, variant) }
  if (variant == "v2") CheckoutV2() else CheckoutV1()
}

// Every event carries what the readout needs in order to cohort correctly
fun Analytics.trackExperimentAware(name: String, props: Map<String, Any?>) = track(
  name,
  props + mapOf(
    "app_version" to BuildConfig.VERSION_NAME,
    "platform" to "android",
    "variant" to exp.variant(checkoutExp),
    // day 0 is this user's first exposure, NOT the calendar date
    "days_since_exposure" to exp.daysSinceFirstExposure(checkoutExp)
  )
)

// The stopping rule is written down before the first user is bucketed
data class Horizon(val minDays: Int = 14, val minExposedPerArm: Int = 34_000)

fun readable(h: Horizon, s: ExperimentStats): Boolean =
  s.daysRunning >= h.minDays &&
    s.perArmExposed.all { it >= h.minExposedPerArm } &&
    s.sampleRatioPValue > 0.01        // an SRM invalidates the whole readout

// Thresholds are agreed before the first user is bucketed, not after the winner is known
data class Guardrail(val metric: String, val maxRegression: Double, val unit: String)

val guardrails = listOf(
