  Guardrail("anr_rate", 0.05, "pp"),
  Guardrail("cold_start_p90_ms", 50.0, "ms"),
  Guardrail("download_size_mb", 1.0, "MB")
)

// Cold start reported where the app is actually usable, tagged with what you will segment on
class StartupReporter(private val analytics: Analytics, private val exp: ExperimentClient) {
  private val started = SystemClock.elapsedRealtime()

  fun onContentVisible(activity: Activity) {
    activity.reportFullyDrawn()                // Play Vitals reads this as fully-drawn time
    analytics.track("cold_start", mapOf(
      "ms" to SystemClock.elapsedRealtime() - started,
      "device_tier" to DeviceTier.of(activity).name,   // the readout is per tier
      "variant" to exp.variant(checkoutExp)
    ))
  }
}

// The decision is per segment, never on the pooled average
fun shipDecision(s: ExperimentStats): Decision = when {
  s.breached("crash_free_users") -> Decision.Block
  s.liftIn(DeviceTier.LOW) < 0.0 -> Decision.HoldAndFixStartup
  else -> Decision.ShipWithTrackedRegression("cold_start_p90_ms", 80)
}

