// 1. Aggregate - 500 impressions become one event with everything the metric needs
class ImpressionBatcher(private val analytics: Analytics) {
  private val seen = LinkedHashSet<String>()

  fun onItemVisible(id: String) { seen += id }

  fun onScreenLeft(screen: String) {
    if (seen.isEmpty()) return
    analytics.track("feed_impressions",
      mapOf("screen" to screen, "count" to seen.size, "item_ids" to seen.toList()))
    seen.clear()
  }
}

// 2 + 3. Sample users, keep money and errors whole, and record the rate on the event
class SamplingSink(private val inner: AnalyticsSink, userId: String) : AnalyticsSink {
  private val bucket = (userId.hashCode().toLong() and 0x7fffffff) % 100

  private fun rateFor(name: String): Int = when {
    name in ALWAYS_KEEP -> 100                 // errors, purchases, experiment_exposure
    name == "feed_impressions" -> 10           // high volume, and only a rate is read from it
    else -> 100
  }

  override fun track(event: AnalyticsEvent) {
    val rate = rateFor(event.name)
    if (bucket >= rate) return                 // user-level, so the funnel still joins
    inner.track(event.withProp("sample_rate", rate))   // count * 100 / rate at query time
  }
}

