// Deny by default before any Kotlin of yours runs - the manifest covers the very first launch
// <meta-data android:name="google_analytics_default_allow_analytics_storage"
//            android:value="false" />
// <meta-data android:name="google_analytics_default_allow_ad_user_data" android:value="false" />

class App : Application() {
  override fun onCreate() {
    super.onCreate()
    applyConsent(ConsentStore(this).current() ?: Consent.allDenied())
    // Analytics and marketing SDKs are NOT started here - they wait for an answer
  }

  private fun applyConsent(c: Consent) = Firebase.analytics.setConsent(mapOf(
    ConsentType.ANALYTICS_STORAGE to c.analytics.toStatus(),
    ConsentType.AD_STORAGE to c.ads.toStatus(),
    ConsentType.AD_USER_DATA to c.ads.toStatus(),
    ConsentType.AD_PERSONALIZATION to c.ads.toStatus()
  ))
}

// Pre-consent events wait on disk, tagged with the category each one needs
class ConsentQueue(private val store: EventStore, private val sink: AnalyticsSink) {

  fun enqueue(e: AnalyticsEvent, needs: Category) = store.append(e, needs)

  fun onAnswer(c: Consent) {
    if (c.analytics) AnalyticsSdk.start()      // gate initialisation, not just sending
    store.drain { event, needs -> if (c.grants(needs)) sink.track(event) }
    store.deleteAll()                          // ungranted events are dropped, never kept
  }

  fun onWithdrawal() {
    store.deleteAll()
    identity.rotateAnonymousId()               // old and new data must not be joinable
  }
}

// Measure the denial itself, or a reworded prompt looks like a product regression
fun onConsentAnswered(c: Consent, att: ATTStatus) = sink.trackEssential(
  "consent_answered",
  mapOf("analytics" to c.analytics, "ads" to c.ads, "att" to att.name)
)
